/* Launch Radar — dark terminal theme. No network, no images, no web fonts. */
:root {
  --bg: #0b0f14; --panel: #11161d; --panel2: #151c25; --line: #232d3a;
  --ink: #e6edf3; --muted: #8b98a9; --faint: #5c6b7d;
  --green: #3fb68b; --amber: #e3b341; --red: #f47067; --blue: #6cb6ff; --violet: #b083f0;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}
* { box-sizing: border-box; }
html { background: var(--bg); }
body { margin: 0; background: var(--bg); color: var(--ink); font-family: var(--sans); font-size: 15px; line-height: 1.5; }
.skip { position: absolute; left: -999px; top: 0; background: var(--green); color: #06110c; padding: 8px 12px; z-index: 9; }
.skip:focus { left: 8px; top: 8px; }
.shell { max-width: 1180px; margin: 0 auto; padding: 0 20px 48px; }
a { color: var(--blue); }
.num, td.num, .mono { font-family: var(--mono); font-variant-numeric: tabular-nums; }
.pos { color: var(--green); } .neg { color: var(--red); }
.sub { color: var(--muted); font-size: 13px; }
h1 { font-size: 30px; line-height: 1.15; margin: 0 0 8px; letter-spacing: -0.02em; }
h2 { font-size: 19px; margin: 0 0 6px; }
h3 { font-size: 15px; margin: 0 0 6px; }

/* header */
.top { display: flex; justify-content: space-between; align-items: baseline; gap: 16px; padding: 18px 0 14px; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.brand { font-family: var(--mono); font-weight: 700; font-size: 18px; letter-spacing: 0.04em; }
.brand .dot { color: var(--green); }
.top-meta { display: flex; gap: 8px; flex-wrap: wrap; }
.pill { font-family: var(--mono); font-size: 12px; color: var(--muted); border: 1px solid var(--line); border-radius: 999px; padding: 3px 10px; white-space: nowrap; }
.pill b { color: var(--ink); font-weight: 600; }

/* lede + stats */
.lede { padding: 26px 0 6px; }
.lede p { max-width: 78ch; color: var(--muted); margin: 0 0 18px; }
.lede p b { color: var(--ink); }
.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin: 4px 0 22px; }
.stat { background: var(--panel); border: 1px solid var(--line); border-radius: 10px; padding: 12px 14px; }
.stat span { display: block; color: var(--muted); font-size: 12px; text-transform: uppercase; letter-spacing: 0.06em; }
.stat b { font-family: var(--mono); font-size: 22px; font-weight: 650; }
.stat small { display: block; color: var(--faint); font-size: 12px; }

/* leaders */
.leaders { display: grid; grid-template-columns: repeat(5, 1fr); gap: 10px; margin: 0 0 22px; }
.leader { background: var(--panel2); border: 1px solid var(--line); border-radius: 10px; padding: 12px; cursor: pointer; text-align: left; color: var(--ink); font: inherit; }
.leader:hover, .leader:focus-visible { border-color: var(--green); outline: none; }
.leader .rank { font-family: var(--mono); color: var(--green); font-size: 12px; }
.leader b { display: block; font-size: 15px; margin: 2px 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.leader .num { font-size: 15px; color: var(--amber); }
.leader small { display: block; color: var(--muted); font-size: 12px; }

/* comps */
.panel { background: var(--panel); border: 1px solid var(--line); border-radius: 12px; padding: 16px 18px; margin: 0 0 22px; }
.panel > p { color: var(--muted); margin: 0 0 12px; max-width: 80ch; }
.comps { width: 100%; border-collapse: collapse; font-size: 13px; }
.comps th, .comps td { text-align: left; padding: 5px 10px 5px 0; border-bottom: 1px solid var(--line); }
.comps th { color: var(--faint); font-weight: 600; text-transform: uppercase; font-size: 11px; letter-spacing: 0.05em; }
.comps td.num { text-align: right; }
.comps th.num { text-align: right; }
details.comps-wrap summary { cursor: pointer; color: var(--blue); font-size: 14px; margin-bottom: 8px; }

/* controls */
.controls { display: flex; gap: 10px; align-items: end; flex-wrap: wrap; margin: 0 0 12px; }
.field { display: flex; flex-direction: column; gap: 4px; }
.field label, .field .sub { font-size: 12px; color: var(--muted); }
.field input, .field select { background: var(--panel); color: var(--ink); border: 1px solid var(--line); border-radius: 8px; padding: 8px 10px; font: inherit; font-size: 14px; }
.field input { min-width: 240px; }
.field input:focus, .field select:focus { border-color: var(--green); outline: none; }
.tabs { display: flex; border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.tabs button { background: transparent; color: var(--muted); border: 0; padding: 8px 14px; font: inherit; font-size: 14px; cursor: pointer; }
.tabs button[aria-pressed="true"] { background: var(--green); color: #06110c; font-weight: 600; }
.check { display: flex; align-items: center; gap: 6px; font-size: 14px; color: var(--muted); padding-bottom: 8px; }
.check input { accent-color: var(--green); width: 16px; height: 16px; }
.count { margin-left: auto; color: var(--muted); font-size: 13px; padding-bottom: 8px; }

/* board table */
.table-wrap { overflow-x: auto; }
table.board { width: 100%; border-collapse: collapse; font-size: 14px; }
.board caption { text-align: left; color: var(--muted); font-size: 13px; padding-bottom: 8px; }
.board th, .board td { padding: 9px 10px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: middle; }
.board th { color: var(--faint); font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; }
.board th.num, .board td.num { text-align: right; }
.board tbody tr { cursor: pointer; }
.board tbody tr:hover { background: var(--panel2); }
.board tbody tr[data-selected="true"] { background: #14202b; box-shadow: inset 3px 0 0 var(--green); }
.board .name b { display: block; font-size: 14px; }
.board .name span { color: var(--muted); font-size: 12px; }
.bar { height: 6px; background: var(--line); border-radius: 3px; overflow: hidden; margin-bottom: 4px; min-width: 90px; }
.bar i { display: block; height: 100%; background: var(--green); }
.tag { font-family: var(--mono); font-size: 11px; border: 1px solid var(--line); border-radius: 4px; padding: 2px 6px; color: var(--amber); white-space: nowrap; }
.tag.live { color: var(--blue); }
.empty { text-align: center; padding: 28px 12px; }
.button { background: var(--green); color: #06110c; border: 0; border-radius: 8px; padding: 9px 16px; font: inherit; font-weight: 600; cursor: pointer; }
.button.ghost { background: transparent; color: var(--ink); border: 1px solid var(--line); }

/* detail */
.detail { border-top: 2px solid var(--green); margin: 0 0 22px; }
.detail-head { display: flex; justify-content: space-between; gap: 16px; align-items: start; flex-wrap: wrap; }
.detail-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-top: 12px; }
.kv { display: grid; grid-template-columns: auto 1fr; gap: 4px 14px; font-size: 14px; }
.kv dt { color: var(--muted); }
.kv dd { margin: 0; font-family: var(--mono); text-align: right; }
.formula { font-family: var(--mono); font-size: 13px; background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; overflow-x: auto; white-space: nowrap; margin: 10px 0; }
.steps { margin: 6px 0 0; padding-left: 20px; }
.steps li { margin-bottom: 10px; }
.steps li b { display: block; font-weight: 600; }
.steps .cost { color: var(--muted); font-size: 13px; }
.note { color: var(--muted); font-size: 13px; margin-top: 12px; }

/* method + footer */
.method p { color: var(--muted); margin: 0 0 10px; max-width: 82ch; }
.method p b { color: var(--ink); }
footer { color: var(--faint); font-size: 12px; border-top: 1px solid var(--line); padding-top: 14px; margin-top: 8px; }
@media (max-width: 900px) {
  .stats { grid-template-columns: repeat(2, 1fr); }
  .leaders { grid-template-columns: repeat(2, 1fr); }
  .detail-grid { grid-template-columns: 1fr; }
  h1 { font-size: 24px; }
}
